# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA İBADET KAVRAMI VE KAPSAMI (ZÂRİYÂT, 51/56)</text>\n  <rect x="25" y="48" width="315" height="185" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ÖZEL (DAR) ANLAMDA İBADETLER</text>\n  <text x="42" y="98" font-size="11" fill="#1e3a8a">• Belirli vakit, şart, rükün ve şekillere bağlıdır:</text>\n  <text x="52" y="120" font-size="11" font-weight="bold" fill="#1d4ed8">1. Namaz (Salât) — Bedenî İbadet</text>\n  <text x="52" y="142" font-size="11" font-weight="bold" fill="#1d4ed8">2. Oruç (Savm) — Bedenî İbadet</text>\n  <text x="52" y="164" font-size="11" font-weight="bold" fill="#1d4ed8">3. Zekât — Malî İbadet</text>\n  <text x="52" y="186" font-size="11" font-weight="bold" fill="#1d4ed8">4. Hac — Hem Bedenî Hem Malî İbadet</text>\n  <text x="182" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Mükellef Şartı: Akıl + Ergenlik (Bülûğ)</text>\n  <rect x="360" y="48" width="315" height="185" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">GENEL (GENİŞ) ANLAMDA İBADET</text>\n  <text x="377" y="98" font-size="11" fill="#14532d">• Allah rızası niyetiyle yapılan her salih ameldir:</text>\n  <text x="387" y="120" font-size="11" fill="#14532d">• Helal rızık kazanmak için dürüstçe çalışmak</text>\n  <text x="387" y="142" font-size="11" fill="#14532d">• Faydalı ilim öğrenmek ve insanlara öğretmek</text>\n  <text x="387" y="164" font-size="11" fill="#14532d">• Anne-babaya, komşulara ve muhtaçlara iyilik</text>\n  <text x="387" y="186" font-size="11" fill="#14532d">• Doğayı korumak, canlılara merhamet göstermek</text>\n  <text x="517" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Ölçüt: Halis niyet ve İslam ahlakına uygunluk</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İBADETLERİN KABUL ŞARTLARI VE KOLAYLIK İLKESİ</text>\n  <rect x="20" y="45" width="320" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">3 TEMEL KABUL ŞARTI</text>\n  <text x="35" y="95" font-size="11" font-weight="bold" fill="#78350f">1. Sahih İman:</text>\n  <text x="125" y="95" font-size="11" fill="#78350f">Tevhid ve inanç esaslarına tam bağlılık</text>\n  <text x="35" y="125" font-size="11" font-weight="bold" fill="#78350f">2. İhlas:</text>\n  <text x="95" y="125" font-size="11" fill="#78350f">Riya ve gösterişten uzak, Allah rızası</text>\n  <text x="35" y="155" font-size="11" font-weight="bold" fill="#78350f">3. Sünnete Uygunluk:</text>\n  <text x="165" y="155" font-size="11" fill="#78350f">Bid\'attan uzak uygulama</text>\n  <rect x="35" y="180" width="290" height="32" rx="6" fill="#fde68a"/>\n  <text x="180" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">"Beni nasıl namaz kılarken gördüyseniz öyle kılın."</text>\n  <rect x="360" y="45" width="320" height="182" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#075985">İBADETLERDE KOLAYLIK VE İTİDAL</text>\n  <text x="375" y="95" font-size="11" fill="#0c4a6e">• Allah kimseye gücünün üstünde yük yüklemez.</text>\n  <text x="375" y="120" font-size="11" fill="#0c4a6e">• Su bulunmadığında <tspan font-weight="bold">teyemmüm</tspan> ruhsatı vardır.</text>\n  <text x="375" y="145" font-size="11" fill="#0c4a6e">• Yolculukta 4 rekâtlı farz namazlar 2 rekât kılınır.</text>\n  <text x="375" y="170" font-size="11" fill="#0c4a6e">• Ayakta duramayan <tspan font-weight="bold">oturarak veya ima ile</tspan> kılar.</text>\n  <rect x="375" y="185" width="290" height="28" rx="6" fill="#bae6fd"/>\n  <text x="520" y="203" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">İlke: Az da olsa devamlı olan amel makbuldür.</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İBADETLERİN BİREYSEL VE TOPLUMSAL KAZANIMLARI</text>\n  <rect x="25" y="45" width="315" height="182" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">BİREYE KAZANDIRDIKLARI</text>\n  <text x="42" y="95" font-size="11" fill="#14532d">• Kalp huzuru, iç güven ve ümit (Ra\'d, 13/28)</text>\n  <text x="42" y="118" font-size="11" fill="#14532d">• Zamanı planlama ve öz disiplin bilinci</text>\n  <text x="42" y="141" font-size="11" fill="#14532d">• Abdest ve gusülle beden-elbise temizliği</text>\n  <text x="42" y="164" font-size="11" fill="#14532d">• Hayasızlık ve kötülükten korunma (Ankebût 45)</text>\n  <text x="42" y="187" font-size="11" fill="#14532d">• Sabır, şükür, tevazu ve sorumluluk bilinci</text>\n  <rect x="360" y="45" width="315" height="182" rx="10" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">TOPLUMA KAZANDIRDIKLARI</text>\n  <text x="377" y="95" font-size="11" fill="#581c87">• Cemaat, cuma, bayram ve hac ile kardeşlik</text>\n  <text x="377" y="118" font-size="11" fill="#581c87">• Zekât, fitre ve sadaka ile sosyal adalet</text>\n  <text x="377" y="141" font-size="11" fill="#581c87">• Oruç ve kurban ile empati ve yardımlaşma</text>\n  <text x="377" y="164" font-size="11" fill="#581c87">• Zararlı alışkanlıkların ve suçların azalması</text>\n  <text x="377" y="187" font-size="11" fill="#581c87">• Toplumsal barış, güven ve karşılıklı sevgi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
